import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem92 corrige fragmento Termolar sem prometer conservacao ou modificar operacao',()=>{const p={id:'MEkEjNiiDdi5MpmlP07R',titulo:'Garrafa térmica Termolar Lúmina Bomba de Pressão 1L',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,p.titulo);assert.deepEqual(correctProductData(x),x);assert.doesNotMatch(x.comentario,/além das informações|\d+ horas|ampola de vidro|inquebrável/i);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');});
